<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$action=$_POST['action']??'';if(!$id||$id===(int)user()['id'])$error='Invalid account. You cannot deactivate your own account.';elseif($action!=='toggle')$error='Unknown action.';else{try{$s=$pdo->prepare("UPDATE users SET is_active=IF(is_active=1,0,1) WHERE id=? AND role='client'");$s->execute([$id]);if(!$s->rowCount())$error='Client account not found.';else{flash('success','Client account status updated.');redirect('users.php');}}catch(Throwable $ex){error_log($ex->__toString());$error='Could not update account.';}}}$users=$pdo->query("SELECT u.id,u.name,u.email,u.phone,u.is_active,u.created_at,COUNT(b.id) booking_count FROM users u LEFT JOIN bookings b ON b.user_id=u.id WHERE u.role='client' GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();page_header('Manage clients');?><p class="muted">Client accounts are created through registration. Admins can activate or deactivate accounts.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Contact</th><th>Bookings</th><th>Account</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['phone']?:'—')?></td><td><?=(int)$u['booking_count']?></td><td><?=$u['is_active']?'Active':'Inactive'?></td><td><form method="post" onsubmit="return confirm('Change this client account status?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><input type="hidden" name="action" value="toggle"><button class="button small <?= $u['is_active']?'danger':'secondary' ?>" type="submit"><?=$u['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php page_footer();?>
